//! Species base-stats table (S-4): the numeric/enum fields of `gSpeciesInfo`.
//!
//! Ports the flat base-data fields of every species from the upstream reference
//! `pokeemerald/src/data/pokemon/species_info.h` (`gSpeciesInfo[]`) — base
//! stats, types, catch rate, base experience, EV yields, held items, gender
//! ratio, egg cycles, base friendship, growth rate, egg groups, abilities,
//! safari-zone flee rate, body colour, and the sprite `noFlip` flag. The struct
//! shape is `struct SpeciesInfo` in `pokeemerald/include/pokemon.h`; the enum
//! constants (`GROWTH_*`, `EGG_GROUP_*`, `BODY_COLOR_*`, `MON_*`) live in
//! `pokeemerald/include/constants/pokemon.h`.
//!
//! Out of scope for this slice (gated on other pipelines): graphics / sprite /
//! palette / icon pointers, cries, learnsets, and Pokédex text.
//!
//! The data is re-expressed idiomatically rather than copied `(no-verbatim)`:
//! each numeric field is a typed value, and the C designated-initializer struct
//! is replaced by an owned [`SpeciesTable`] `(oop-boundaries)`. Values are
//! pinned back to upstream by the unit tests below `(behavioral-fidelity)`.

use crate::error::AssetError;
use crate::type_chart::Type;

/// A species identifier, matching the upstream `SPECIES_*` ids.
///
/// `SpeciesId(0)` is the reserved `SPECIES_NONE` slot (an all-zero entry
/// upstream); real species run `1..=NUM` in national-dex-ish order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct SpeciesId(pub u16);

/// An ability identifier, matching the upstream `ABILITY_*` ids.
///
/// Modelled as a newtype rather than a ~350-variant enum: the honest bounded
/// choice for a field this slice only needs to carry, not interpret.
/// `AbilityId(0)` is `ABILITY_NONE` (the empty second-ability slot).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct AbilityId(pub u16);

/// A held-item identifier, matching the upstream `ITEM_*` ids.
///
/// A newtype for the same reason as [`AbilityId`]; `ItemId(0)` is `ITEM_NONE`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ItemId(pub u16);

/// A species' experience-growth curve — the upstream `GROWTH_*` constants.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum GrowthRate {
    /// `GROWTH_MEDIUM_FAST` (0).
    MediumFast = 0,
    /// `GROWTH_ERRATIC` (1).
    Erratic = 1,
    /// `GROWTH_FLUCTUATING` (2).
    Fluctuating = 2,
    /// `GROWTH_MEDIUM_SLOW` (3).
    MediumSlow = 3,
    /// `GROWTH_FAST` (4).
    Fast = 4,
    /// `GROWTH_SLOW` (5).
    Slow = 5,
}

/// A breeding egg group — the upstream `EGG_GROUP_*` constants.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum EggGroup {
    /// `EGG_GROUP_NONE` (0); appears only in the `SPECIES_NONE` slot.
    None = 0,
    /// `EGG_GROUP_MONSTER` (1).
    Monster = 1,
    /// `EGG_GROUP_WATER_1` (2).
    Water1 = 2,
    /// `EGG_GROUP_BUG` (3).
    Bug = 3,
    /// `EGG_GROUP_FLYING` (4).
    Flying = 4,
    /// `EGG_GROUP_FIELD` (5).
    Field = 5,
    /// `EGG_GROUP_FAIRY` (6).
    Fairy = 6,
    /// `EGG_GROUP_GRASS` (7).
    Grass = 7,
    /// `EGG_GROUP_HUMAN_LIKE` (8).
    HumanLike = 8,
    /// `EGG_GROUP_WATER_3` (9).
    Water3 = 9,
    /// `EGG_GROUP_MINERAL` (10).
    Mineral = 10,
    /// `EGG_GROUP_AMORPHOUS` (11).
    Amorphous = 11,
    /// `EGG_GROUP_WATER_2` (12).
    Water2 = 12,
    /// `EGG_GROUP_DITTO` (13).
    Ditto = 13,
    /// `EGG_GROUP_DRAGON` (14).
    Dragon = 14,
    /// `EGG_GROUP_NO_EGGS_DISCOVERED` (15).
    NoEggsDiscovered = 15,
}

/// A species' body colour, used by the Pokédex — the `BODY_COLOR_*` constants.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum BodyColor {
    /// `BODY_COLOR_RED` (0).
    Red = 0,
    /// `BODY_COLOR_BLUE` (1).
    Blue = 1,
    /// `BODY_COLOR_YELLOW` (2).
    Yellow = 2,
    /// `BODY_COLOR_GREEN` (3).
    Green = 3,
    /// `BODY_COLOR_BLACK` (4).
    Black = 4,
    /// `BODY_COLOR_BROWN` (5).
    Brown = 5,
    /// `BODY_COLOR_PURPLE` (6).
    Purple = 6,
    /// `BODY_COLOR_GRAY` (7).
    Gray = 7,
    /// `BODY_COLOR_WHITE` (8).
    White = 8,
    /// `BODY_COLOR_PINK` (9).
    Pink = 9,
}

/// How a species' gender is distributed.
///
/// Upstream packs this into a single `genderRatio` byte where `0x00` is
/// always-male, `0xFE` (`MON_FEMALE`) always-female, `0xFF` (`MON_GENDERLESS`)
/// genderless, and any other value `n` means the female probability is
/// `n / 256`. We model the three sentinels honestly instead of leaking magic
/// bytes; [`GenderRatio::Ratio`] carries the raw female-weight for the rest.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum GenderRatio {
    /// `MON_GENDERLESS` (`0xFF`): the species has no gender.
    Genderless,
    /// `0x00`: every member is male.
    AlwaysMale,
    /// `MON_FEMALE` (`0xFE`): every member is female.
    AlwaysFemale,
    /// A mixed ratio: the raw `genderRatio` byte, the female weight out of 256.
    Ratio(u8),
}

impl GenderRatio {
    /// Reconstruct the raw upstream `genderRatio` byte.
    #[must_use]
    pub const fn raw(self) -> u8 {
        match self {
            Self::Genderless => 0xFF,
            Self::AlwaysMale => 0x00,
            Self::AlwaysFemale => 0xFE,
            Self::Ratio(n) => n,
        }
    }
}

/// The effort values a species awards when defeated, per stat (each `0..=3`;
/// upstream stores these as two-bit `evYield_*` bitfields).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct EvYield {
    /// HP EVs awarded.
    pub hp: u8,
    /// Attack EVs awarded.
    pub attack: u8,
    /// Defense EVs awarded.
    pub defense: u8,
    /// Speed EVs awarded.
    pub speed: u8,
    /// Special Attack EVs awarded.
    pub sp_attack: u8,
    /// Special Defense EVs awarded.
    pub sp_defense: u8,
}

/// The flat numeric/enum base-data of a single species `(oop-boundaries)`.
///
/// One field per upstream `struct SpeciesInfo` member in this slice's scope.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct BaseStats {
    /// Base HP stat.
    pub hp: u8,
    /// Base Attack stat.
    pub attack: u8,
    /// Base Defense stat.
    pub defense: u8,
    /// Base Speed stat.
    pub speed: u8,
    /// Base Special Attack stat.
    pub sp_attack: u8,
    /// Base Special Defense stat.
    pub sp_defense: u8,
    /// The species' one or two types (a single-type species repeats its type).
    pub types: [Type; 2],
    /// Catch rate (`0..=255`; higher is easier).
    pub catch_rate: u8,
    /// Base experience yield.
    pub base_exp: u8,
    /// Effort values awarded on defeat.
    pub ev_yield: EvYield,
    /// Common wild held item (`ITEM_NONE` when absent).
    pub held_common: ItemId,
    /// Rare wild held item (`ITEM_NONE` when absent).
    pub held_rare: ItemId,
    /// Gender distribution.
    pub gender_ratio: GenderRatio,
    /// Egg cycles (steps-to-hatch counter, in units of 255 steps).
    pub egg_cycles: u8,
    /// Base friendship a caught member starts with.
    pub base_friendship: u8,
    /// Experience-growth curve.
    pub growth_rate: GrowthRate,
    /// The species' one or two egg groups.
    pub egg_groups: [EggGroup; 2],
    /// Possible abilities; slot 1 is `ABILITY_NONE` when there is only one.
    pub abilities: [AbilityId; 2],
    /// Safari-zone flee rate.
    pub safari_flee_rate: u8,
    /// Pokédex body colour.
    pub body_color: BodyColor,
    /// When set, the sprite is never horizontally flipped.
    pub no_flip: bool,
}

