/// Owned, read-only access to the extracted species base-data
/// `(oop-boundaries)`. Holds no mutable state; construct once with
/// [`SpeciesTable::new`] and share it.
#[derive(Debug, Clone, Copy)]
pub struct SpeciesTable {
    data: &'static [BaseStats],
}

impl SpeciesTable {
    /// The number of addressable [`SpeciesId`] slots, including `SPECIES_NONE`.
    pub const LEN: usize = SPECIES_DATA.len();

    /// [`SpeciesTable::LEN`] as a [`u16`], the width of a [`SpeciesId`].
    ///
    /// The table has far fewer than `u16::MAX` entries, so this conversion is
    /// exact; the `assert!` makes that a compile-time fact and lets callers do
    /// id arithmetic without a lossy `as` cast.
    pub const LEN_U16: u16 = {
        assert!(SPECIES_DATA.len() <= u16::MAX as usize);
        #[allow(clippy::cast_possible_truncation)]
        {
            SPECIES_DATA.len() as u16
        }
    };

    /// Build the table over the extracted upstream data.
    #[must_use]
    pub const fn new() -> Self {
        Self { data: SPECIES_DATA }
    }

    /// The base-data for `species`, or `None` if the id is out of range.
    #[must_use]
    pub fn get(&self, species: SpeciesId) -> Option<&'static BaseStats> {
        self.data.get(species.0 as usize)
    }

    /// The base-data for `species`.
    ///
    /// # Errors
    ///
    /// Returns [`AssetError::UnknownSpecies`] if `species` is outside the
    /// extracted range `0..`[`SpeciesTable::LEN`].
    pub fn base_stats(&self, species: SpeciesId) -> Result<&'static BaseStats, AssetError> {
        self.get(species)
            .ok_or(AssetError::UnknownSpecies(species.0))
    }

    /// The number of addressable species slots (including `SPECIES_NONE`).
    #[must_use]
    pub fn len(&self) -> usize {
        self.data.len()
    }

    /// Whether the table has no entries (never true for the extracted data).
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.data.is_empty()
    }
}

impl Default for SpeciesTable {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::{
        AbilityId, BaseStats, BodyColor, EggGroup, EvYield, GenderRatio, GrowthRate, ItemId,
        SpeciesId, SpeciesTable,
    };
    use crate::error::AssetError;
    use crate::type_chart::Type;

    // National-dex ids of the species pinned by the tie test.
    const BULBASAUR: SpeciesId = SpeciesId(1);
    const CHARMANDER: SpeciesId = SpeciesId(4);
    const CHARIZARD: SpeciesId = SpeciesId(6);
    const PIKACHU: SpeciesId = SpeciesId(25);
    const MAGNEMITE: SpeciesId = SpeciesId(81);

    #[test]
    fn table_has_species_none_plus_411_species() {
        // Upstream `gSpeciesInfo` covers `SPECIES_NONE` (id 0) plus ids
        // `1..=411`, a dense range — so the table is exactly 412 slots.
        assert_eq!(SpeciesTable::LEN, 412);
        assert_eq!(SpeciesTable::new().len(), 412);
        assert!(!SpeciesTable::new().is_empty());
    }

    #[test]
    fn species_none_is_the_zero_entry() {
        // `[SPECIES_NONE] = {0}` upstream: every numeric field zero, enums at
        // their zero discriminant.
        let table = SpeciesTable::new();
        let none = table.base_stats(SpeciesId(0)).unwrap();
        assert_eq!(none.hp, 0);
        assert_eq!(none.attack, 0);
        assert_eq!(none.base_exp, 0);
        assert_eq!(none.types, [Type::Normal, Type::Normal]);
        assert_eq!(none.gender_ratio, GenderRatio::AlwaysMale);
        assert_eq!(none.growth_rate, GrowthRate::MediumFast);
        assert_eq!(none.egg_groups, [EggGroup::None, EggGroup::None]);
        assert_eq!(none.body_color, BodyColor::Red);
        assert_eq!(none.abilities, [AbilityId(0), AbilityId(0)]);
    }

    #[test]
    fn out_of_range_lookup_is_reported() {
        let table = SpeciesTable::new();
        let bad = SpeciesId(SpeciesTable::LEN_U16);
        assert_eq!(table.get(bad), None);
        assert_eq!(
            table.base_stats(bad),
            Err(AssetError::UnknownSpecies(SpeciesTable::LEN_U16)),
        );
    }

    #[test]
    fn gender_ratio_raw_round_trips_sentinels_and_mixes() {
        assert_eq!(GenderRatio::Genderless.raw(), 0xFF);
        assert_eq!(GenderRatio::AlwaysMale.raw(), 0x00);
        assert_eq!(GenderRatio::AlwaysFemale.raw(), 0xFE);
        assert_eq!(GenderRatio::Ratio(31).raw(), 31);
    }

    /// Upstream-tie test: pins the full [`BaseStats`] of a representative
    /// sample straight back to `species_info.h` so no transcribed value can
    /// silently drift `(behavioral-fidelity)`. Covers a dual-type starter
    /// (Bulbasaur Grass/Poison), a single-type one (Charmander Fire), a
    /// Fire/Flying (Charizard), a mono-Electric with held items and a mixed
    /// gender ratio (Pikachu), and a genderless Steel type (Magnemite).
    // Long by design: each species is a full field-by-field literal transcribed
    // from `species_info.h`; splitting it would only obscure the tie.
    #[allow(clippy::too_many_lines)]
    #[test]
    fn sample_matches_upstream_species_info() {
        let table = SpeciesTable::new();

        assert_eq!(
            *table.base_stats(BULBASAUR).unwrap(),
            BaseStats {
                hp: 45,
                attack: 49,
                defense: 49,
                speed: 45,
                sp_attack: 65,
                sp_defense: 65,
                types: [Type::Grass, Type::Poison],
                catch_rate: 45,
                base_exp: 64,
                ev_yield: EvYield {
                    hp: 0,
                    attack: 0,
                    defense: 0,
                    speed: 0,
                    sp_attack: 1,
                    sp_defense: 0,
                },
                held_common: ItemId(0),
                held_rare: ItemId(0),
                gender_ratio: GenderRatio::Ratio(31),
                egg_cycles: 20,
                base_friendship: 70,
                growth_rate: GrowthRate::MediumSlow,
                egg_groups: [EggGroup::Monster, EggGroup::Grass],
                abilities: [AbilityId(65), AbilityId(0)],
                safari_flee_rate: 0,
                body_color: BodyColor::Green,
                no_flip: false,
            },
        );

        assert_eq!(
            *table.base_stats(CHARMANDER).unwrap(),
            BaseStats {
                hp: 39,
                attack: 52,
                defense: 43,
                speed: 65,
                sp_attack: 60,
                sp_defense: 50,
                types: [Type::Fire, Type::Fire],
                catch_rate: 45,
                base_exp: 65,
                ev_yield: EvYield {
                    hp: 0,
                    attack: 0,
                    defense: 0,
                    speed: 1,
                    sp_attack: 0,
                    sp_defense: 0,
                },
                held_common: ItemId(0),
                held_rare: ItemId(0),
                gender_ratio: GenderRatio::Ratio(31),
                egg_cycles: 20,
                base_friendship: 70,
                growth_rate: GrowthRate::MediumSlow,
                egg_groups: [EggGroup::Monster, EggGroup::Dragon],
                abilities: [AbilityId(66), AbilityId(0)],
                safari_flee_rate: 0,
                body_color: BodyColor::Red,
                no_flip: false,
            },
        );

        assert_eq!(
            *table.base_stats(CHARIZARD).unwrap(),
            BaseStats {
                hp: 78,
                attack: 84,
                defense: 78,
                speed: 100,
                sp_attack: 109,
                sp_defense: 85,
                types: [Type::Fire, Type::Flying],
                catch_rate: 45,
                base_exp: 209,
                ev_yield: EvYield {
                    hp: 0,
                    attack: 0,
                    defense: 0,
                    speed: 0,
                    sp_attack: 3,
                    sp_defense: 0,
                },
                held_common: ItemId(0),
                held_rare: ItemId(0),
                gender_ratio: GenderRatio::Ratio(31),
                egg_cycles: 20,
                base_friendship: 70,
                growth_rate: GrowthRate::MediumSlow,
                egg_groups: [EggGroup::Monster, EggGroup::Dragon],
                abilities: [AbilityId(66), AbilityId(0)],
                safari_flee_rate: 0,
                body_color: BodyColor::Red,
                no_flip: false,
            },
        );

        assert_eq!(
            *table.base_stats(PIKACHU).unwrap(),
            BaseStats {
                hp: 35,
                attack: 55,
                defense: 30,
                speed: 90,
                sp_attack: 50,
                sp_defense: 40,
                types: [Type::Electric, Type::Electric],
                catch_rate: 190,
                base_exp: 82,
                ev_yield: EvYield {
                    hp: 0,
                    attack: 0,
                    defense: 0,
                    speed: 2,
                    sp_attack: 0,
                    sp_defense: 0,
                },
                held_common: ItemId(139),
                held_rare: ItemId(202),
                gender_ratio: GenderRatio::Ratio(127),
                egg_cycles: 10,
                base_friendship: 70,
                growth_rate: GrowthRate::MediumFast,
                egg_groups: [EggGroup::Field, EggGroup::Fairy],
                abilities: [AbilityId(9), AbilityId(0)],
                safari_flee_rate: 6,
                body_color: BodyColor::Yellow,
                no_flip: false,
            },
        );

        assert_eq!(
            *table.base_stats(MAGNEMITE).unwrap(),
            BaseStats {
                hp: 25,
                attack: 35,
                defense: 70,
                speed: 45,
                sp_attack: 95,
                sp_defense: 55,
                types: [Type::Electric, Type::Steel],
                catch_rate: 190,
                base_exp: 89,
                ev_yield: EvYield {
                    hp: 0,
                    attack: 0,
                    defense: 0,
                    speed: 0,
                    sp_attack: 1,
                    sp_defense: 0,
                },
                held_common: ItemId(0),
                held_rare: ItemId(199),
                gender_ratio: GenderRatio::Genderless,
                egg_cycles: 20,
                base_friendship: 70,
                growth_rate: GrowthRate::MediumFast,
                egg_groups: [EggGroup::Mineral, EggGroup::Mineral],
                abilities: [AbilityId(42), AbilityId(5)],
                safari_flee_rate: 0,
                body_color: BodyColor::Gray,
                no_flip: false,
            },
        );
    }

    #[test]
    fn ev_yields_stay_within_two_bits() {
        // Every `evYield_*` is a 2-bit upstream bitfield, so each decoded value
        // must be `0..=3` across the whole table.
        let table = SpeciesTable::new();
        for id in 0..SpeciesTable::LEN_U16 {
            let ev = table.base_stats(SpeciesId(id)).unwrap().ev_yield;
            for v in [
                ev.hp,
                ev.attack,
                ev.defense,
                ev.speed,
                ev.sp_attack,
                ev.sp_defense,
            ] {
                assert!(v <= 3, "species {id} EV out of 2-bit range: {v}");
            }
        }
    }
}
